      return;
    }
    try {
      command.run(this.createContext(args));
    } catch (error) {
      this.print(`${name}: ${error.message}`, "err");
    }
    this.updatePrompt();
    this.applyLocale();
  },

  onKeydown(event) {
    const { input } = this.els;
    if (this.busy) {
      event.preventDefault();
      if (event.key === "Escape" || (event.ctrlKey && event.key.toLowerCase() === "c")) this.end();
      return;
    }
    if (event.key === "Escape") {
      event.preventDefault();
      this.setOpen(false);
    } else if (event.key === "ArrowUp") {
