      missingOperand: "{name}: missing operand",
      usage: "usage: {usage}",
      nothingToOpen: "{name}: nothing to open",
      opening: "opening {name}...",
      themeNow: "theme set to {name}",
      themeUnknown: "unknown theme '{name}'. available: {list}",
