      const bodyBottom = bodyBottoms[Math.floor(Math.random() * bodyBottoms.length)];
      const y = GROUND - bodyBottom - PTERO_BODY_TOP - PTERO_BODY_H;
      obstacles.push({ type: "ptero", x: W + 10, y, w: PTERO_W, h: PTERO_H });
