import { Model } from 'assets/js/model.js';
import { View } from 'assets/js/view.js';
import { TerminalFS } from 'assets/functions/Terminal/Filesystem.js';
import { TerminalEffects } from 'assets/functions/Terminal/Effects.js';

export const TerminalCommands = {
  messages: {
