import { Model } from '../../js/model.js';
import { View } from '../../js/view.js';
import { TerminalCommands } from './Commands.js';

export const TerminalFS = {
  slug(text) {
    return text.toLowerCase().replace(/['’]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  },

  bar(level) {
    const filled = Math.round(level / 10);
    return "█".repeat(filled) + "░".repeat(10 - filled);
  },

  dir(children) {
    return { type: "dir", children };
  },

  file(text, href = null) {
    return { type: "file", text, href };
  },

  describe(item) {
    const lines = [View.localized(item, "title"), `${View.localized(item, "tag")} · ${View.localized(item, "meta")}`, "", View.localized(item, "desc")];
    if (item.url) lines.push("", item.url);
    return lines.join("\n");
  },

  build() {
