    this.cleanup?.();
    this.cleanup = null;
    this.els.form.classList.remove("is-busy");
    this.updatePrompt();
    this.els.input.focus({ preventScroll: true });
  },

  submit() {
    if (this.busy) return;
    const { input } = this.els;
    const line = input.value.trim();
    this.echo(input.value);
    input.value = "";
    this.draft = "";
    if (!line) return;

