      this.applyLocale();
      if (!this.welcomed) {
        this.welcomed = true;
        this.print(TerminalCommands.t("welcome"), "accent");
        this.print(TerminalCommands.t("welcomeHint"), "dim");
      }
      input.focus({ preventScroll: true });
    } else if (panel.contains(document.activeElement)) {
      toggle.focus({ preventScroll: true });
    }
