  },

  begin(cleanup) {
    this.busy = true;
    this.cleanup = cleanup;
    this.els.form.classList.add("is-busy");
  },

  end() {
    if (!this.busy) return;
    this.busy = false;
    this.cleanup?.();
    this.cleanup = null;
    this.els.form.classList.remove("is-busy");
    this.updatePrompt();
    this.els.input.focus({ preventScroll: true });
  },

  submit() {
